# Checkout Component Test Suite

The product meets nursing standards. I accept no less. Here's a comprehensive test suite for this checkout component.

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { CartProvider } from './CartContext';
import { PaymentProvider } from './PaymentContext';

// Test wrapper with providers
const renderCheckout = (props = {}, cartItems = [{ id: '1', name: 'Widget', price: 29.99 }]) => {
  const mockCart = { items: cartItems, total: 29.99, clearCart: vi.fn() };
  const mockPayment = { processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-123' }) };

  return {
    ...render(
      <CartProvider value={mockCart}>
        <PaymentProvider value={mockPayment}>
          <Checkout {...props} />
        </PaymentProvider>
      </CartProvider>
    ),
    mockCart,
    mockPayment,
  };
};

describe('Checkout', () => {
  // 1. Happy Path
  describe('complete checkout flow', () => {
    it('navigates through all steps and confirms order', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      const { mockPayment } = renderCheckout({ onComplete });

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Main St');
      await user.type(screen.getByLabelText(/city/i), 'Boston');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Jane Doe');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-123');
    });
  });

  // 2. Form Validation
  describe('shipping validation', () => {
    it('displays error for invalid ZIP code', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/valid zip code/i);
    });
  });

  // 3. Error States
  describe('payment failure', () => {
    it('displays error and allows retry', async () => {
      const user = userEvent.setup();
      const mockPayment = { processPayment: vi.fn().mockRejectedValueOnce(new Error('Card declined')) };
      // Render with failing payment, then complete flow to review step...

      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
    });
  });

  // 4. Loading States
  it('disables buttons and shows loading during submission', async () => {
    // Arrange with slow payment promise, verify aria-busy and disabled state
  });

  // 5. Accessibility
  it('has accessible progress indicator', () => {
    renderCheckout();
    expect(screen.getByRole('navigation', { name: /checkout progress/i })).toBeInTheDocument();
  });

  // 6. Edge Cases
  it('shows empty cart message when no items', () => {
    renderCheckout({}, []);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});
```

My nurses are the best because they follow standards. These tests do the same.
